var report="Tools/EnemyAnimation/SlimeKingStatesVerification.txt";System.IO.File.WriteAllText(report,"Slime boss sprite states verification\n");
int phase=0,wait=0,lastFrame=-1;double started=UnityEditor.EditorApplication.timeSinceStartup;SlimeKing king=null;EnemySpriteAnimation anim=null;System.Collections.IEnumerator routine=null;
var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=null;UnityEditor.EditorApplication.isPlaying=false;};
tick=()=>{try{
 if(!UnityEditor.EditorApplication.isPlaying)return;UnityEngine.Application.runInBackground=true;
 if(UnityEditor.EditorApplication.timeSinceStartup-started>70)throw new System.Exception("timeout phase "+phase);
 if(lastFrame==UnityEngine.Time.frameCount)return;lastFrame=UnityEngine.Time.frameCount;
 if(phase==0){if(StageManager.Instance==null||PoolManager.Instance==null||++wait<12)return;StageManager.Instance.StopRun();PoolManager.Instance.ResetActiveObjects();var player=UnityEngine.GameObject.FindGameObjectWithTag("Player");player.GetComponent<PlayerMove>().enabled=false;king=PoolManager.Instance.Spawn(151,(UnityEngine.Vector2)player.transform.position+UnityEngine.Vector2.up*8).GetComponent<SlimeKing>();king.StopAllCoroutines();king.GetComponent<UnityEngine.AI.NavMeshAgent>().enabled=false;king.enemyMove.enabled=false;anim=king.GetComponent<EnemySpriteAnimation>();routine=(System.Collections.IEnumerator)typeof(SlimeKing).GetMethod("OpenBodyPattern",flags).Invoke(king,null);if(!routine.MoveNext()||!anim.IsPlaying("OpenBodyRaise"))throw new System.Exception("Raise missing");if(!routine.MoveNext()||!anim.IsPlaying("OpenBodyHold"))throw new System.Exception("Hold missing");king.openDuration=0;if(!routine.MoveNext()||!anim.IsPlaying("OpenBodyLower"))throw new System.Exception("Lower missing");routine.MoveNext();if(!anim.IsPlaying("Move"))throw new System.Exception("Move missing after opening");System.IO.File.AppendAllText(report,"PASS open, hold, lower and return to move\n");
 typeof(SlimeKing).GetField("playerTf",flags).SetValue(king,player.transform);king.slideOvershoot=30;king.obstacleMask=0;routine=(System.Collections.IEnumerator)typeof(SlimeKing).GetMethod("SlidePattern",flags).Invoke(king,null);if(!routine.MoveNext()||!anim.IsPlaying("SlidePrepare"))throw new System.Exception("Slide prepare missing");float expected=king.slidePrepareClip.length/UnityEngine.Mathf.Max(.01f,king.slideWindup);if(UnityEngine.Mathf.Abs(anim.Speed-expected)>.001f)throw new System.Exception("Slide preparation speed mismatch");if(!routine.MoveNext()||!anim.IsPlaying("SlideStart"))throw new System.Exception("Slide start missing");phase=1;return;}
 if(phase==1&&anim.IsPlaying("SlideLoop")){System.IO.File.AppendAllText(report,"PASS slide preparation timing and transition into loop\n");GameManager.Instance.burnChance=0;GameManager.Instance.moldChance=0;king.splitSpawnCount=0;king.ResetHealth(100);king.TakeDamage(101,king.transform.position);if(!anim.IsPlaying("Hit"))throw new System.Exception("Lethal hit failed to interrupt slide");System.IO.File.AppendAllText(report,"PASS lethal hit interrupts slide\nCOMPLETE\n");finish();}
}catch(System.Exception e){System.IO.File.AppendAllText(report,"FAIL "+e+"\n");finish();}};
UnityEditor.EditorApplication.update+=tick;UnityEditor.EditorApplication.isPlaying=true;return "Started slime boss animation pattern test";
